    CInputEvent event;
    if (DJoystick != 0)
    {
        EmptyEventStore();
        UpdateAcquired();
        long result = DJoystick->Poll();
        if (result == DIERR_INPUTLOST)
        {
            DJoystick->Acquire();
            result = DJoystick->Poll();
